import pages
P_=[('overview','Pradoṣa','Śiva’s Twilight, Twice a Month'),('nilakantha','Nīlakaṇṭha','The Poison, the Blue Throat and the Dance on Nandi'),('vrata-katha','The Pradoṣa Vrata Kathā','Śāṇḍilya, the Widow and the Two Boys'),('pradosha-stotram','The Pradoṣa Stotrāṣṭakam','The Hymn of the Twilight Hour'),('keeping-the-vow','Keeping the Pradoṣa Vow','The Fast, the Hour and the Worship'),('weekday-pradoshas','The Seven Pradoṣas','Soma, Bhauma, Śani and the Rest'),('in-temples','Pradoṣa in Temples','Nandi, the Crescent Path and the Procession'),('masa-shivaratri','Māsa Śivarātri','The Night After Pradoṣa')]
PG.configure('/festivals/pradosha/',P_,'navy','Pradoṣa','Lord','Pradoṣa'); PG.OUT='outx/pradosha/'
L=pages.link
PR=[l.strip() for l in open('prad.txt').read().strip().split('\n')]
NANDI=lambda: beast('bull','#f4f1ea')
LING='<path d="M-34 0 h68 l-8 -12 h-52z" fill="#8a8f9a"/><path d="M-30 -12 h60 q10 0 14 6 l-8 4" fill="#8a8f9a"/><path d="M-14 -12 v-38 q14 -16 28 0 v38z" fill="#3a3a40"/>'
DUSK='#3a3a5a'
def R(id,t,sub,f,ps,tk,k): return reading(id,t,sub,f,ps,tk,k)
def dusk(): return '<rect width="560" height="190" fill="#e8a87c"/><rect y="0" width="560" height="80" fill="#5a5a8a"/>'
SH=lambda: shiva()
def hala(): return '<path d="M-30 0 q-10 -40 10 -60 q20 -30 40 0 q20 20 0 60z" fill="#2a3a5a" stroke="#111" stroke-width="2"/>'
def churn(): return '<path d="M0 0 v-120" stroke="#8a7a5a" stroke-width="18"/><path d="M-60 -40 q60 -20 120 0 q-60 20 -120 0" fill="none" stroke="#2a9d6f" stroke-width="7"/>'+'<g transform="translate(0 10)"><path d="M-30 0 q30 -20 60 0 q-30 16 -60 0z" fill="#5a7a5a"/></g>'
# ================= 1 overview
i=0
COV=covart('A Śiva liṅga at twilight with Nandi before it, the sky turning orange and violet, a lamp lit',dusk().replace('560','440').replace('190','196')+g(260,190,1.4,LING)+g(140,196,1,NANDI())+g(340,190,1.2,lamp())+g(380,40,1,moon()))
pp=[foreword(i,['Twice every lunar month, as the sun sets on the thirteenth day (<b>Trayodaśī</b>), Śiva temples fill. The hour between day and night, <b>Pradoṣa</b>, is held to be Śiva’s own; on it the gods gather on Kailāsa to watch him dance. The vow kept at that hour is the <b>Pradoṣa vrata</b>, the Śaiva counterpart of the Vaiṣṇava <a href="/festivals/ekadashi/">Ekādaśī</a>.','This 8-part series covers Pradoṣa fully: the hour, the story of Nīlakaṇṭha, the vrata story of Śāṇḍilya, the Skanda Purāṇa’s Pradoṣa hymn verse by verse, how the vow is kept, the seven weekday Pradoṣas, the worship in temples, and Māsa Śivarātri, the night that follows.'],[('z','Why the thirteenth day?'),('b','Because on a thirteenth day, at twilight, Śiva saved the worlds from the poison. That hour has been his ever since.')]),
 glance([('Name','Pradoṣa (Sanskrit), Pradōṣam (Tamil), Pradoṣa vrata'),('When','Trayodaśī (13th lunar day) of both fortnights, at twilight'),('The hour','Pradoṣa kāla: roughly 90 minutes either side of sunset (sources differ)'),('Deity','Śiva, with Pārvatī; Nandi worshipped first'),('Story','Śiva drinks the hālāhala poison and becomes Nīlakaṇṭha; he dances between Nandi’s horns'),('Great forms','Śani Pradoṣa (Saturday), Soma Pradoṣa (Monday)'),('Next day','Caturdaśī: Māsa Śivarātri')],svg(560,140,'A liṅga with Nandi at twilight',dusk()+g(320,130,1.2,LING)+g(180,135,.9,NANDI()))),
 R('word','THE WORD “PRADOṢA”','Twilight, the start of night',svg(560,170,'A sky graded from day to night with the sun setting and the first star',dusk().replace('190','170')+g(280,150,1,sun(22))+'<rect y="150" width="560" height="20" fill="#3a3a5a"/>'+'<circle cx="480" cy="30" r="3" fill="#fff8d0"/>'),['<b>The word.</b> <i>Pradoṣa</i> means the beginning of night: the twilight after sunset. A Purāṇic genealogy even makes Pradoṣa a person, son of Kalpa and Doṣā (night), brother of Niśītha (midnight) and Vyuṣṭa (dawn).','<b>Two meanings.</b> It names both the daily twilight hour and, above all, the twilight of every Trayodaśī, when the vow is kept.','<b>Sandhyā.</b> Junctions of time, dawn and dusk, are sacred in all Hindu worship; the evening sandhyā belongs especially to Śiva, the lord of transitions.','<b>Not “doṣa”.</b> The word looks like <i>doṣa</i>, fault, and some popular sermons play on that (“the hour that removes faults”); the plain meaning is simply early night.'],[('z','So Pradoṣa is a time, not a day?'),('b','A time on a day: twilight on the thirteenth. Miss the hour and, strictly, you have missed the Pradoṣa.')],'Pradoṣa: <b>twilight, Śiva’s hour</b>.'),
 R('tithi','THE THIRTEENTH DAY','Trayodaśī, twice a month',svg(560,130,'Fifteen moon phases with the thirteenth circled',''.join(f'<circle cx="{30+k*35}" cy="60" r="13" fill="{"#fff8d0" if k<13 else "#cfd8e6"}" stroke="#111" stroke-width="1.5"/>' for k in range(15))+'<circle cx="450" cy="60" r="19" fill="none" stroke="#c0392b" stroke-width="3"/>'+lab(450,105,'13th: Trayodaśī')),['<b>Two a month.</b> Every lunar month has two Trayodaśīs, one in each fortnight, so there are about 24 Pradoṣas a year.','<b>Which day?</b> The Pradoṣa is kept on the day when Trayodaśī prevails at sunset. Almanacs (<a href="/festivals/panchanga/">pañcāṅga</a>) mark it; sometimes it falls on the 12th by the calendar.','<b>Next to Ekādaśī.</b> It comes two days after Ekādaśī: Viṣṇu’s day, then Śiva’s twilight. Many devotees keep both.','<b>Then Caturdaśī.</b> The day after is Caturdaśī; in the dark fortnight it is Māsa Śivarātri ('+L(7,'Part 8')+').'],[('z','Ekādaśī for Viṣṇu, Trayodaśī for Śiva?'),('b','Exactly. The fortnight has its own rhythm: eleventh, thirteenth, fourteenth.')],'The 13th lunar day, <b>at sunset</b>.'),
 R('gods','WHY THE GODS GATHER','The scene on Kailāsa',svg(560,190,'Śiva dancing on Kailāsa with Pārvatī seated and gods playing instruments around',g(280,180,1.1,SH())+g(140,180,.8,devi(items=('lotus',)))+''.join(g(x,180,.7,god(c)) for x,c in [(400,'#1d6fb8'),(450,'#c0392b'),(500,'#e0a800')])+g(420,120,.5,vina())),['<b>The dance.</b> The Skanda Purāṇa’s Pradoṣa hymn ('+L(3,'Part 4')+') describes the scene: Śiva seats Gaurī on a jewelled throne on Kailāsa and wishes to dance; at that hour all the gods come to serve him.','<b>The orchestra.</b> Sarasvatī plays the vīṇā, Indra the flute, Brahmā keeps time, Lakṣmī sings and Viṣṇu plays the mṛdaṅga.','<b>Everyone present.</b> Gandharvas, yakṣas, siddhas and every being of the three worlds stand at Śiva’s side.','<b>So worship Śiva alone.</b> The hymn concludes: at Pradoṣa, worship Śiva; all the other gods are pleased through him, because they are all with him then.'],[('z','Viṣṇu playing the drum for Śiva?'),('b','In this hymn, yes. At this one hour the gods are Śiva’s orchestra, and worshipping him honours them all.')],'At twilight <b>all the gods are with Śiva</b>.'),
 story('origin','THE ORIGIN STORY IN BRIEF','Why Pradoṣa began',strip('Three panels: the ocean churned; the dark poison rising; Śiva drinking it',[panel([(churn(),.8)],'#dfe9f6',None),panel([(hala(),1.4)],'#5a5a8a',150),panel([(SH(),.9)],'#e8a87c',150)],['the ocean is churned','the poison rises','Śiva drinks it']),'The full story is in '+L(1,'Part 2')+'; here is the outline.',['Gods and demons churned the ocean of milk for the nectar of immortality.','First came not nectar but <b>hālāhala</b>, a poison that began to burn the worlds.','The terrified gods ran to Śiva on Kailāsa; tradition says it was the Trayodaśī, at twilight.','Śiva drank the poison; Pārvatī held his throat, and it stayed there, turning it blue: <b>Nīlakaṇṭha</b>.','Then, in joy at the worlds saved, he danced, and the gods worshipped him. That twilight became Pradoṣa.'],[('z','He danced after drinking poison?'),('b','To show the worlds he was unharmed, the story says. The dance is a celebration of rescue.')],'Poison drunk, the worlds saved, <b>Śiva dances at twilight</b>.'),
 R('nandi','NANDI FIRST','Why the bull is worshipped at Pradoṣa',svg(560,170,'Devotees bathing Nandi with milk in front of a shrine',g(280,150,1.6,NANDI())+'<path d="M300 60 q-10 30 -20 50" stroke="#fff" stroke-width="5" fill="none"/>'+g(440,150,1,person('#c0392b'))),['<b>The doorkeeper.</b> Nandi, Śiva’s bull and chief attendant, sits facing the sanctum in every Śiva temple.','<b>At Pradoṣa.</b> In South Indian temples Nandi receives a full abhiṣeka at Pradoṣa, bathed in milk, curd, honey and sandal, before the liṅga is worshipped.','<b>The story.</b> One telling says Nandi carried the poison to Śiva and was dazed by its fumes; Śiva calmed him by dancing between his horns. Another says Nandi led the frightened gods around Kailāsa to reach Śiva.','<b>Seeing Śiva between the horns.</b> Devotees look at the liṅga through the space between Nandi’s horns, as if seeing the dance from Nandi’s place ('+L(6,'Part 7')+').'],[('z','Why the bull before God?'),('b','Because Nandi was there, and helped. You greet the doorkeeper, then the Lord.')],'Nandi is bathed first: <b>Śiva’s first devotee</b>.'),
 R('fruits','WHAT PRADOṢA IS SAID TO GIVE','The promises of the texts',svg(560,160,'A lamp, coins, a family and a healthy figure, symbols of the promised fruits',g(100,140,1.3,lamp())+g(220,140,1,'<circle r="14" fill="#e0a800" stroke="#111"/>')+g(340,140,1,person('#2a9d6f'))+g(380,140,.8,child())+g(480,140,1,sun(16))),['<b>The hymn’s promise.</b> The Pradoṣa hymn says frankly: those who worship Śiva at Pradoṣa grow in wealth, grain, family and good fortune in this very world; those who neglect it stay poor through many births.','<b>Release.</b> Popular tradition adds freedom from sin, debt, illness and planetary troubles, especially Saturn’s.','<b>Read honestly.</b> These are the promises of devotional texts. The deeper teaching of the same hymn is in its first verse: in a worthless world, the one essential thing is service at the Lord’s feet.','<b>No bargain.</b> Teachers warn against treating the vow as a transaction; sincerity is its whole power.'],[('z','So it’s for getting rich?'),('b','The hymn starts by saying the only real wealth is serving Śiva’s feet. The rest is a promise to draw people in.')],'Wealth promised, <b>devotion meant</b>.'),
 R('series','THIS SERIES','Eight parts on Pradoṣa',svg(560,130,'Eight numbered tiles',''.join(f'<rect x="{40+k*62}" y="30" width="50" height="60" rx="8" fill="#e3eaf3" stroke="#111" stroke-width="2"/>'+txt(65+k*62,72,str(k+1),26,fill='#0b2a4a') for k in range(8))),['<b>The story.</b> '+L(1,'Part 2, Nīlakaṇṭha')+': the churning, the poison and the dance; '+L(2,'Part 3, the Vrata Kathā')+': Śāṇḍilya’s story of the widow and the two boys.','<b>The hymn.</b> '+L(3,'Part 4')+': the Pradoṣa Stotrāṣṭakam, verse by verse.','<b>The practice.</b> '+L(4,'Part 5, keeping the vow')+'; '+L(5,'Part 6, the seven weekday Pradoṣas')+'; '+L(6,'Part 7, Pradoṣa in temples')+'.','<b>The night after.</b> '+L(7,'Part 8, Māsa Śivarātri')+', and the link to <a href="/festivals/maha-shivaratri/">Mahā Śivarātri</a>.'],[('z','Can I start keeping Pradoṣa from this?'),('b','Read Part 5 first. Then go to a Śiva temple at sunset on the next Trayodaśī.')],'Story, hymn, practice, temples, <b>the night after</b>.'),
R('compare','PRADOṢA AND EKĀDAŚĪ','Two fortnightly vows',svg(560,150,'Two lamps, one blue for Viṣṇu on the 11th and one at dusk for Śiva on the 13th',g(180,120,1.6,lamp('#1d6fb8'))+g(380,120,1.6,lamp('#e8a87c'))+lab(180,145,'11th: Ekādaśī')+lab(380,145,'13th: Pradoṣa')),['<b>Two vows, two days apart.</b> <a href="/festivals/ekadashi/">Ekādaśī</a> (11th) belongs to Viṣṇu; Pradoṣa (13th) to Śiva. Many households keep both.','<b>Different centres.</b> Ekādaśī is a whole-day fast ending the next morning; Pradoṣa centres on one twilight hour, with the fast ending that evening.','<b>Different tones.</b> Ekādaśī stories are about release through fasting and vigil; Pradoṣa stories about Śiva’s rescue at twilight.','<b>No rivalry.</b> The tradition keeps both as gifts of the same fortnight.'],[('z','Can a Vaiṣṇava keep Pradoṣa?'),('b','Many Smārta households keep both without a second thought. The hymn itself has Viṣṇu playing drum for Śiva.')],'Ekādaśī for Viṣṇu, Pradoṣa for Śiva: <b>both in one fortnight</b>.'),
 end(i,['<b>Hour.</b> Pradoṣa: twilight, the start of night.','<b>Day.</b> Trayodaśī of both fortnights: about 24 a year.','<b>Story.</b> Śiva drank the poison and danced; the gods worshipped him.','<b>Nandi.</b> Bathed first; Śiva seen between his horns.','<b>Promise.</b> Devotion at Śiva’s feet, and the good it brings.'],'Part 2 tells the whole story: the churning of the ocean, the poison, Nīlakaṇṭha, and the dance on Nandi.','Pradoṣa'),
 sources([('Pradoṣa:','Wikipedia, “Pradosha” (twilight worship on Trayodaśī, Nandi, Śani and Soma Pradoṣa, procession). Skanda Purāṇa, Pradoṣa Stotrāṣṭakam (sanskritdocuments.org, pradosha8).'),('Story:','Bhāgavata Purāṇa 8.7 (Śiva drinks the poison); Tamil temple tradition (Nandi, dance).')],'the exact length of pradoṣa kāla (90 minutes, three hours, or 2 ghaṭikās in different sources); the Trayodaśī timing of the poison story (popular tradition).','Popular traditions are marked as such.')]
build(i,'PART 1 OF 8 · TWILIGHT · THE 13TH DAY',COV,'Śiva’s twilight','What <b>Pradoṣa</b> is, the <b>13th day</b>, why the gods gather, the origin in brief, <b>Nandi first</b>, and what the vow is said to give.','Pradoṣa explained: Śiva’s twilight hour on Trayodaśī, twice a month; the scene on Kailāsa, the origin story, Nandi’s worship, the fruits promised, and a map of the 8-part series. Part 1 of the illustrated Pradoṣa series.',pp)
# ================= 2 Nīlakaṇṭha
i=1
COV=covart('Śiva drinking a dark poison from his cupped hands, Pārvatī holding his throat, which turns blue, gods and demons watching',g(220,196,1.3,SH())+g(320,196,1.1,devi(items=('abhaya',)))+g(80,196,.8,god())+g(390,196,.8,demon())+g(220,80,.7,hala()))
pp=[foreword(i,['This is the story at the heart of Pradoṣa: the churning of the ocean, the poison that rose first, and Śiva who drank it. It is told in the Bhāgavata Purāṇa (book 8) and many other Purāṇas, and loved in South Indian temple tradition, which adds the dance on Nandi.','We tell it in order, scene by scene, with what each part means.'],[('z','Why did the gods churn an ocean?'),('b','For amṛta, the nectar of immortality. They had lost their strength and needed it back.')]),
 glance([('Source','Bhāgavata Purāṇa 8.5–8; also Mahābhārata, Viṣṇu and Śiva Purāṇas'),('Why','The gods, weakened by Durvāsas’s curse, sought amṛta'),('Tools','Mount Mandara as the churning rod, the serpent Vāsuki as the rope'),('Help','Viṣṇu as Kūrma, the tortoise, held the mountain'),('First out','Hālāhala (kālakūṭa), the world-burning poison'),('Śiva','Drank it; Pārvatī held his throat: Nīlakaṇṭha'),('After','Treasures, Lakṣmī, and at last amṛta; Viṣṇu as Mohinī')],svg(560,150,'The churning of the ocean',river(560,110,'#dfe9f6')+g(280,120,1,churn()))),
 story('curse','THE CURSE OF DURVĀSAS','How the gods lost their strength',strip('Three panels: the sage Durvāsas offering a garland; Indra’s elephant crushing it; the sage cursing',[panel([(sage('#c0392b'),.9),(lotus(),.7)],'#fff3cf',140),panel([(elephant(False),.6)],'#e9e3f5',140),panel([(sage('#c0392b'),.9)],'#fde4e4',140)],['a garland given','trampled','the curse']),'The Viṣṇu Purāṇa tells how it began.',['The sage <b>Durvāsas</b>, famous for his temper, gave Indra a divine garland.','Indra carelessly placed it on his elephant Airāvata, who threw it down and trampled it.','Durvāsas cursed Indra and the gods to lose their glory and strength.','The demons attacked and defeated the weakened gods.','The gods went to Viṣṇu, who advised them: make peace with the demons, churn the ocean together, and win amṛta.'],[('z','All that over a garland?'),('b','Over pride. Indra treated a holy gift carelessly. The whole churning starts from one act of arrogance.')],'A garland trampled, <b>the gods’ strength lost</b>.'),
 story('churning','THE CHURNING','Mandara, Vāsuki and the tortoise',strip('Three panels: gods and demons pulling a serpent wound round a mountain; the mountain sinking; a giant tortoise holding it up',[panel([(god(),.6),(churn(),.6),(demon(),.6)],'#dfe9f6',150),panel([(churn(),.7)],'#5a7a9a',None),panel([('<ellipse rx="50" ry="18" fill="#5a7a5a" stroke="#111" stroke-width="2"/>',1),(churn(),.5)],'#dfe9f6',150)],['the great tug','the mountain sinks','Kūrma holds it']),'Bhāgavata Purāṇa 8.6–7.',['Gods and demons uprooted <b>Mount Mandara</b> to use as a churning rod, and wound the serpent king <b>Vāsuki</b> round it as the rope.','The demons took the head end, the gods the tail, and they pulled back and forth.','The mountain, with no base, began to sink into the ocean.','Viṣṇu took the form of <b>Kūrma</b>, a giant tortoise, and held the mountain on his back. See our <a href="/vishnu/dashavatara/">Daśāvatāra series</a>.','The churning went on, and the ocean began to give up its hidden things.'],[('z','The demons took the head end on purpose?'),('b','They insisted, thinking it the place of honour. They got the serpent’s fiery breath for their pride.')],'Mountain, serpent, tortoise: <b>the ocean is churned</b>.'),
 story('poison','THE POISON RISES','Hālāhala',strip('Three panels: dark smoke rising from the ocean; gods and demons fleeing; the worlds beginning to burn',[panel([(hala(),1.5)],'#5a5a8a',150),panel([(god(),.6),(demon(),.6)],'#e8a87c',150),panel([(flames(),1.4)],'#2a2a3a',150)],['hālāhala','everyone flees','the worlds burn']),'The first thing out of the ocean was not nectar.',['Before any treasure, the ocean released <b>hālāhala</b> (also kālakūṭa), a poison so terrible that its fumes alone burned everything they touched.','Gods and demons alike dropped the serpent and ran.','The poison spread across the three worlds; creatures fainted, the sky darkened.','No god could stop it.','The gods ran to Kailāsa, to Śiva. South Indian tradition says it was the Trayodaśī evening: the first Pradoṣa.'],[('z','Why poison first?'),('b','Many teachers read it as the inner churning: when you start to dig into yourself, the poison comes up before the nectar.')],'Before the nectar, <b>the poison</b>.'),
 story('drink','ŚIVA DRINKS','Nīlakaṇṭha',strip('Three panels: the gods praying to Śiva; Śiva drinking from his palm; Pārvatī holding his throat, now blue',[panel([(god(),.6),(god('#c0392b'),.6),(SH(),.6)],'#dfe9f6',150),panel([(SH(),.9),(hala(),.5)],'#e8a87c',150),panel([(SH().replace('#9fb7d6','#4a6aa6'),.8),(devi(items=('abhaya',)),.6)],'#fff3cf',150)],['the gods’ prayer','he drinks','the blue throat']),'Bhāgavata Purāṇa 8.7.',['The gods praised Śiva as the lord of all and begged him to save the worlds.','Śiva, full of compassion, told Pārvatī that a great one protects living beings even at a cost to himself.','He gathered the poison into his palm and drank it.','Pārvatī pressed his throat so it would not go down; in many tellings Śiva himself held it there. It stayed in his throat and turned it blue.','He became <b>Nīlakaṇṭha</b>, “the blue-throated”. A few drops spilled, the Bhāgavata says, and were taken by snakes, scorpions and poisonous plants.'],[('z','Did it hurt him?'),('b','The texts say it only coloured his throat. Its mark is his badge: the one who takes the world’s poison.')],'The poison held in his throat: <b>Nīlakaṇṭha</b>.'),
 story('dance','THE DANCE ON NANDI','South Indian temple tradition',strip('Three panels: Nandi dazed by the fumes; Śiva dancing between Nandi’s horns; the gods worshipping',[panel([(NANDI(),.9)],'#e9e3f5',150),panel([(NANDI(),.7),(SH(),.6)],'#e8a87c',150),panel([(god(),.6),(god('#c0392b'),.6),(god('#e0a800'),.6)],'#fff3cf',150)],['Nandi dazed','the dance between the horns','the gods rejoice']),'Tamil Śaiva tradition completes the story.',['In one telling Nandi had carried the poison to Śiva and was dazed by its fumes.','To show the worlds he was unharmed, and to restore Nandi, Śiva danced, standing between Nandi’s horns.','The gods gathered on Kailāsa and worshipped him at that twilight hour, the hour of Pradoṣa.','Ever since, at Pradoṣa, Nandi is worshipped first, and devotees look at Śiva between his horns.','Tellings differ; this is the version behind the temple practice of '+L(6,'Part 7')+'.'],[('z','Is this in the Bhāgavata too?'),('b','No, it’s a living temple tradition. The Purāṇa gives the poison; the temples give the dance.')],'Śiva dances <b>between Nandi’s horns</b>.'),
 R('treasures','WHAT CAME AFTER','The fourteen treasures and the nectar',svg(560,180,'Treasures rising from the ocean: a white elephant, a horse, a wish-granting tree, the moon, Lakṣmī on a lotus, and a pot of nectar',river(560,130,'#dfe9f6')+g(70,130,.6,elephant(False))+g(170,130,.8,beast('donkey','#fff'))+g(260,130,.8,tree())+g(340,90,1,moon())+g(420,130,.8,devi(sari='#e0a800',items=('lotus','lotus')))+g(510,120,1,pot('#e0a800'))),['<b>Treasures.</b> After the poison came the ratnas: Kāmadhenu the wish-cow, the horse Uccaiḥśravas, the elephant Airāvata, the Kaustubha gem, the wish-tree Pārijāta, the apsarās, Vāruṇī, and the moon, which Śiva wears. Lists vary.','<b>Lakṣmī.</b> The goddess Lakṣmī rose on a lotus and chose Viṣṇu.','<b>Dhanvantari.</b> Last came Dhanvantari, physician of the gods, carrying the pot of <b>amṛta</b>.','<b>Mohinī.</b> The demons seized it; Viṣṇu became Mohinī, the enchantress, and gave it to the gods. See our <a href="/festivals/ekadashi/vaishakha/">Mohinī Ekādaśī</a>.'],[('z','The moon came out of the ocean too?'),('b','In the story, yes, and Śiva wears it. That is why Monday, the moon’s day, is so dear to him.')],'Poison first, <b>then the treasures, then nectar</b>.'),
 R('meaning','WHAT IT MEANS','Readings of the story',svg(560,160,'A blue throat drawn as a calm circle, holding a dark swirl without letting it spread',g(280,90,2,'<circle r="30" fill="#4a6aa6" stroke="#111" stroke-width="2"/><path d="M-12 -4 q12 -12 24 0 q-12 12 -24 0z" fill="#2a2a3a"/>')),['<b>Compassion that costs.</b> Śiva takes on what no one else can bear. The Bhāgavata has him say that the great serve beings even at their own risk.','<b>Holding, not swallowing.</b> The poison neither goes down nor comes out: he contains it. Many teachers read this as mastery of anger and pain, held without harming oneself or others.','<b>Poison before nectar.</b> Inner work brings up the worst first; persevere, and the treasures follow.','<b>Pradoṣa.</b> So at twilight, devotees bring their own poisons to Śiva, asking him to hold them.'],[('z','So I can bring my anger to Śiva?'),('b','That is exactly what many devotees do at Pradoṣa. Nīlakaṇṭha holds what we can’t.')],'Nīlakaṇṭha: <b>the one who holds the poison</b>.'),
 R('icon','NĪLAKAṆṬHA IN ART AND TEMPLES','Where to see the blue throat',svg(560,160,'Śiva with a blue throat and a crescent moon, holding a trident',g(280,150,1.5,SH().replace('#9fb7d6','#4a6aa6'))),['<b>The blue throat.</b> Images and paintings of Śiva often show the throat blue, even when the body is white with ash.','<b>Named temples.</b> Many temples honour him as Nīlakaṇṭha; the Nīlakaṇṭha Mahādeva temple near Ṛṣikeśa is said to mark the place where he drank the poison.','<b>Viṣāpaharaṇa.</b> Śiva is also worshipped as <b>Viṣāpaharaṇa-mūrti</b>, “remover of poison”, in some South Indian temples.','<b>In hymns.</b> “Nīlakaṇṭha” and “Śitikaṇṭha” recur in the <a href="/shiva/sri-rudram/">Śrī Rudram</a> and other hymns.'],[('z','Is there a Nīlakaṇṭha in Karnataka?'),('b','Śiva has many temples under that name across India. Nañjanagūḍu’s Nañjuṇḍa, “the one who ate the poison”, is Karnataka’s own: see <a href="/temples-of-india/around-mysuru/nanjangud/">our article</a>.')],'Nañjuṇḍa of Nañjanagūḍu: <b>Karnataka’s poison-eater</b>.'),
 end(i,['<b>Curse.</b> Durvāsas’s curse weakened the gods.','<b>Churning.</b> Mandara, Vāsuki, Kūrma.','<b>Poison.</b> Hālāhala rose first; Śiva drank it: Nīlakaṇṭha.','<b>Dance.</b> On the Trayodaśī twilight, between Nandi’s horns.','<b>After.</b> The treasures, Lakṣmī, amṛta, Mohinī.'],'Part 3 tells the Pradoṣa vrata kathā itself: the sage Śāṇḍilya, a poor widow and two boys.','Nīlakaṇṭha'),
 sources([('Texts:','Bhāgavata Purāṇa 8.5–8 (churning, poison, Nīlakaṇṭha, treasures, Mohinī); Viṣṇu Purāṇa 1.9 (Durvāsas’s curse).'),('Temple tradition:','The dance on Nandi and the Trayodaśī timing: South Indian temple tradition, as summarised in popular sources and Wikipedia, “Pradosha”.')],'the dance-on-Nandi episode and its timing (temple tradition, not the Bhāgavata); lists of the treasures (vary).','Bhāgavata numbering by book and chapter.')]
build(i,'PART 2 OF 8 · THE POISON · THE BLUE THROAT',COV,'The one who held the poison','The story in order: <b>the curse</b>, <b>the churning</b>, <b>the poison</b>, <b>Śiva drinks</b>, <b>the dance on Nandi</b>, what came after, and what it means.','Nīlakaṇṭha and the churning of the ocean: Durvāsas’s curse, Mandara and Vāsuki, Kūrma, the hālāhala poison, Śiva drinking it, the dance on Nandi at Pradoṣa, the treasures and amṛta, and the meaning of the blue throat. Part 2 of the illustrated Pradoṣa series.',pp)
# ================= 3 vrata kathā
i=2
COV=covart('A poor widow with two boys, one princely, meeting a sage at a temple at twilight',dusk().replace('560','440').replace('190','196')+g(130,196,1.1,person('#8a6a4a'))+g(180,196,.9,child())+g(210,196,.9,child())+g(330,196,1.1,sage('#ff8c1a')))
SND=lambda: sage('#ff8c1a')
pp=[foreword(i,['Every vow has its kathā, the story told at the end of the worship. Pradoṣa’s is told in the Skanda Purāṇa: a poor widow, her son, an orphaned prince she takes in, and the sage <b>Śāṇḍilya</b> who teaches them the vow.','The last two verses of the Pradoṣa hymn ('+L(3,'Part 4')+') are Śāṇḍilya’s words to her. Here is the whole story, scene by scene. Names vary between editions; we follow the common telling.'],[('z','Who tells it at the pūjā?'),('b','Often the priest or the eldest at home. It is read after the evening worship.')]),
 glance([('Source','Skanda Purāṇa (Brahmottara Khaṇḍa), the Pradoṣa vrata māhātmya'),('Teacher','The sage Śāṇḍilya'),('The family','A poor brahmin widow; her son Śuciṣmat (Śuciśravas in some tellings)'),('The prince','Dharmagupta of Vidarbha, orphaned and found by the widow'),('The vow','Pradoṣa worship of Śiva, kept by the two boys'),('The fruits','Wealth for the poor boy; a bride and a kingdom for the prince')],svg(560,140,'Two boys praying before a liṅga at dusk',dusk()+g(280,130,1.1,LING)+g(180,135,.8,child())+g(380,135,.8,child()))),
 story('widow','THE WIDOW AND THE FOUNDLING','The beginning',strip('Three panels: a widow begging with her son; finding a baby by a pond; raising the two boys together',[panel([(person('#8a6a4a'),.8),(child(),.7)],'#e9d6c0',140),panel([(river(144,120),1),(child(),.7)],'#dfe9f6',None),panel([(person('#8a6a4a'),.8),(child(),.7),(child(),.7)],'#fff3cf',140)],['a poor widow','a child by the water','two sons']),'The Skanda Purāṇa’s story opens in poverty.',['A poor brahmin widow lived by begging, with her young son <b>Śuciṣmat</b>.','One day she found a baby boy, alone, by a pond: a prince, though she did not know it.','Out of pity she took him home and raised him with her own son as brothers.','She named him and fed both boys with what little she gathered.','The three lived on in poverty, the widow worrying for both their futures.'],[('z','She took in a stranger’s baby when she had nothing?'),('b','That is where the story’s grace begins: her kindness before any vow.')],'A widow’s kindness: <b>two sons where she had one</b>.'),
 story('sage','ŚĀṆḌILYA REVEALS THE PAST','Why they suffer',strip('Three panels: the widow and boys meeting the sage at a temple; the sage seeing the past; the sage explaining',[panel([(SND(),.8),(person('#8a6a4a'),.7)],'#e8a87c',140),panel([(SND(),.8),(sun(14),.6)],'#5a5a8a',140),panel([(SND(),.8),(child(),.6),(child(),.6)],'#fff3cf',140)],['at the temple','the sage sees','the past told']),'At a Śiva temple the family met the sage.',['The widow took the boys to a temple, where the sage <b>Śāṇḍilya</b> sat.','He looked at them with his yogic sight and told her: the foundling is <b>Dharmagupta</b>, son of the king of Vidarbha, whose father was killed by enemies and whose mother died in grief.','He also told her about her own son: in his past life he had been a brahmin who lived by accepting gifts, never giving any. That is why he is poor now (the hymn’s verse 8).','“To remove that fault,” the sage said, “let him take refuge in Śaṅkara” (verse 9).','And he taught them the <b>Pradoṣa vrata</b>.'],[('z','So the hymn’s last verses are part of this story!'),('b','Exactly. The sage speaks them to the widow. That’s why the hymn ends so strangely.')],'Śāṇḍilya reveals the past and <b>teaches the vow</b>.'),
 story('treasure','THE TREASURE','The poor boy’s fortune',strip('Three panels: the boys worshipping at twilight; the poor boy digging by a river; finding a pot of gold',[panel([(LING,.8),(child(),.6),(child(),.6)],'#e8a87c',150),panel([(child(),.8),(river(144,140),1)],'#dfe9f6',150),panel([(pot('#e0a800'),1.4)],'#fff3cf',140)],['the vow kept','by the riverbank','a pot of gold']),'The boys kept the vow with devotion.',['Both boys kept the Pradoṣa worship of Śiva faithfully, Trayodaśī after Trayodaśī.','One day, bathing or digging by a riverbank, Śuciṣmat found a buried pot of treasure.','He wanted to share it with his brother at once.','The family’s poverty ended.','Tellings differ on the details; all agree the poor boy’s fortune turned through the vow.'],[('z','The poor boy found gold?'),('b','His fault was never giving. Notice: the first thing he wants is to share it.')],'The vow kept, <b>a treasure found and shared</b>.'),
 story('princess','THE GANDHARVA PRINCESS','The prince’s fortune',strip('Three panels: celestial maidens playing by a lake; the prince meeting the princess; her father agreeing to the marriage',[panel([(person('#7a3fa0'),.7),(person('#e0a800'),.7),(person('#2a9d6f'),.7)],'#cfe0b8',140),panel([(child(),.9),(person('#7a3fa0'),.8)],'#fff3cf',140),panel([(god('#7a3fa0'),.8),(child(),.7),(person('#7a3fa0'),.7)],'#e9e3f5',140)],['gandharva maidens','the prince and Aṃśumatī','a blessed match']),'Then came the prince’s turn.',['As a young man, Dharmagupta wandered in a forest and came upon gandharva maidens playing by a lake.','Their princess, <b>Aṃśumatī</b>, saw him, and the two fell in love.','Her father, the gandharva king, came to him and said: Śiva had told him to give his daughter to this prince, a devotee of Pradoṣa.','The gandharva king also promised to help him regain his father’s kingdom.','So the orphan found a bride from the heavens.'],[('z','How did the gandharva king know?'),('b','Śiva told him, the story says. The prince’s twilight worship had been seen.')],'An orphan prince, <b>a heavenly bride</b>.'),
 story('kingdom','THE KINGDOM REGAINED','The end of the story',strip('Three panels: the prince leading an army; the enemies defeated; the prince crowned with his queen, mother and brother beside him',[panel([(child(),.8),(bow(),.7)],'#e9e3f5',140),panel([(demon(),.7),(flames(),.7)],'#fde4e4',140),panel([(K,.0) if False else (person('#e0a800'),.8),(person('#7a3fa0'),.7),(person('#8a6a4a'),.7)],'#fff3cf',140)],['to battle','the enemies fall','crowned']),'The story ends in Vidarbha.',['With the gandharvas’ help, Dharmagupta marched on the usurpers who had killed his father.','He defeated them and took back the throne of Vidarbha.','He brought the widow who raised him to the palace as his mother, and made Śuciṣmat his chief companion.','He ruled long and justly, and kept the Pradoṣa vow all his life.','The Purāṇa ends: whoever keeps Pradoṣa, or hears this story, receives Śiva’s grace.'],[('z','He kept the widow as his mother?'),('b','Of course. Her kindness started it all. The story honours her as much as the vow.')],'A throne regained, <b>a foster mother honoured</b>.'),
 R('moral','WHAT THE STORY TEACHES','Lessons of the kathā',svg(560,160,'A widow sharing bread with two boys, and a lamp',g(200,140,1.1,person('#8a6a4a'))+g(270,140,.9,child())+g(320,140,.9,child())+g(440,140,1.4,lamp())),['<b>Kindness first.</b> The story begins with a poor woman taking in a stranger’s child. Grace follows generosity.','<b>Giving, not only receiving.</b> Śuciṣmat’s past life of only taking explains his poverty; his first impulse with the treasure is to share.','<b>Persistence.</b> The boys keep the vow fortnight after fortnight, long before any reward.','<b>Grace for all.</b> One poor, one royal: the vow lifts both.'],[('z','So the vow worked because they were good people?'),('b','The vow and the goodness go together. The story would ring false if the widow had been cruel.')],'Kindness, giving, persistence: <b>the heart of the kathā</b>.'),
 R('other','OTHER PRADOṢA STORIES','The moon, and more',svg(560,160,'The moon, pale and ill, regaining its light before Śiva',g(200,90,1.6,'<circle r="24" fill="#cfd8e6" stroke="#111" stroke-width="2"/>')+'<path d="M240 90 h80" stroke="#111" stroke-width="3"/>'+g(380,90,1.6,'<circle r="24" fill="#fff8d0" stroke="#111" stroke-width="2"/>')+g(470,150,1,SH())),['<b>The moon’s cure.</b> A popular story says Candra, the moon, cursed with a wasting illness by Dakṣa, was relieved by Śiva on a Trayodaśī evening, which is why Pradoṣa is prayed for health. (The moon’s cure is also tied to Somanātha; see our <a href="/temples-of-india/12-jyotirlingas/">Jyotirliṅga series</a>.)','<b>The gods and the demons.</b> Another tradition says the gods, harassed by demons, ran round Kailāsa on a Trayodaśī evening, guided by Nandi, and Śiva saved them.','<b>Weekday stories.</b> Each weekday Pradoṣa has its own kathā in popular vrata books ('+L(5,'Part 6')+').','<b>One theme.</b> In every story, twilight is when Śiva rescues.'],[('z','So many stories for one vow?'),('b','A beloved vow collects stories. The Skanda Purāṇa one is the classic.')],'The moon’s cure, the gods’ rescue: <b>twilight is rescue time</b>.'),
 R('reading','HOW TO READ THE KATHĀ','At the end of the worship',svg(560,150,'A family seated around a lamp while an elder reads from a book',g(280,140,1.2,person('#e0a800',seat=True))+g(280,100,.8,book())+g(170,140,.9,person('#c0392b',seat=True))+g(390,140,.9,child())+g(460,130,1.2,lamp())),['<b>When.</b> After the evening worship and before breaking the fast, the family sits together to hear the kathā.','<b>Who.</b> A priest, an elder or anyone in the family reads it; children love it.','<b>Then.</b> Ārati, prasāda, and the fast is broken.','<b>Our text.</b> This page’s retelling can be read aloud; '+L(3,'Part 4')+' gives the hymn.'],[('z','Can I read it to my kids?'),('b','Perfect. It is a story about two boys, after all.')],'Read the kathā <b>after the worship</b>.'),
 end(i,['<b>Widow.</b> A poor widow takes in a foundling prince.','<b>Sage.</b> Śāṇḍilya reveals the past and teaches Pradoṣa.','<b>Treasure.</b> The poor son finds gold and shares it.','<b>Princess.</b> The prince weds the gandharva Aṃśumatī.','<b>Kingdom.</b> Vidarbha regained; the widow honoured.'],'Part 4 sings the Pradoṣa hymn of the Skanda Purāṇa, verse by verse.','The Pradoṣa vrata kathā'),
 sources([('Story:','Skanda Purāṇa, Brahmottara Khaṇḍa (Pradoṣa māhātmya), as commonly retold; Pradoṣa Stotrāṣṭakam verses 8–9 (sanskritdocuments.org).')],'names (Śuciṣmat/Śuciśravas; the widow’s name) and details differ between editions; the moon story (popular).','Retold in our own words.')]
build(i,'PART 3 OF 8 · ŚĀṆḌILYA · THE TWO BOYS',COV,'A widow, two boys and a sage','The Skanda Purāṇa’s story in six scenes: <b>the foundling</b>, <b>Śāṇḍilya</b>, <b>the treasure</b>, <b>the gandharva princess</b>, <b>the kingdom</b>, and what it teaches.','The Pradoṣa vrata kathā of the Skanda Purāṇa: the poor widow, her son and the foundling prince Dharmagupta, the sage Śāṇḍilya, the treasure, the gandharva princess Aṃśumatī and the kingdom regained. Part 3 of the illustrated Pradoṣa series.',pp)
# ================= 4 stotram
i=3
COV=covart('Śiva dancing on Kailāsa at twilight while Sarasvatī plays the vīṇā, Indra the flute, Brahmā keeps time and Viṣṇu plays the drum',dusk().replace('560','440').replace('190','196')+g(220,196,1.2,SH())+g(80,196,.7,devi(sari='#fff',items=('book',)))+g(120,150,.5,vina())+g(340,196,.8,vishnu())+g(400,196,.7,god('#c0392b')))
M=[('THE ONE ESSENTIAL THING','I speak the truth, I speak what is good for the next world, I speak the essence, the heart of the Upaniṣads: for a creature caught in this harsh, worthless round of births, the one thing of value is service to the lotus feet of the Lord.',[('satyam bravīmi','I speak the truth'),('upaniṣad-hṛdayam','the heart of the Upaniṣads'),('saṃsāram asāram','the worthless round of births'),('īśvara-pada-amburuha','the Lord’s lotus feet'),('sevā','service')],'<b>The real promise first.</b> Before any talk of wealth, the hymn states its core: serving the Lord is the one essential thing.','The one thing that matters: <b>service at Śiva’s feet</b>.'),
 ('THOSE WHO NEGLECT IT','Those who do not worship Giriśa at the time of Pradoṣa, who do not even bow to Śiva when others worship him, who do not drink this story with the cups of their ears: such deluded people are poor, birth after birth.',[('girīśam','Śiva, lord of the mountain'),('samaye pradoṣe','at the time of Pradoṣa'),('śruti-puṭaiḥ','with the cups of the ears'),('mūḍhāḥ','the deluded'),('daridrāḥ','poor')],'<b>A warning.</b> The verse is blunt, as Purāṇic praise often is. Its image is lovely: drinking a sacred story through the ears.','Neglect the hour, <b>stay poor</b>.'),
 ('THOSE WHO KEEP IT','Those who, at the time of Pradoṣa, worship the lotus feet of the Supreme Lord with undivided minds, grow ever richer here in this very world: in wealth, grain, wife, sons, good fortune and prosperity.',[('ananya-manasaḥ','with undivided minds'),('aṅghri-saroja-pūjām','worship of the lotus feet'),('pravṛddha','ever increasing'),('saubhāgya','good fortune'),('iha eva loke','here in this world')],'<b>Undivided.</b> The condition is <i>ananya-manas</i>, a mind on nothing else. The fruits are worldly and frankly listed.','Worship with an undivided mind: <b>fortune here and now</b>.'),
 ('THE DANCE ON KAILĀSA','In his palace on Kailāsa, having seated Gaurī, mother of the three worlds, on a golden jewelled throne, when the trident-bearer wishes to dance, at the time of Pradoṣa, all the gods come to serve him.',[('kailāsa-śaila-bhuvane','in the palace on Mount Kailāsa'),('trijagaj-janitrīm gaurīm','Gaurī, mother of the three worlds'),('ratna-pīṭhe','on a jewelled throne'),('nṛtyam vidhātum','to dance'),('śūla-pāṇau','the trident-bearer')],'<b>Why the hour is holy.</b> Śiva dances for Gaurī, and every god is present. Worship at this hour reaches all of them.','At twilight Śiva dances, <b>and all the gods attend</b>.'),
 ('THE DIVINE ORCHESTRA','Sarasvatī holding the vīṇā, Indra bearing the flute, Brahmā with hands keeping time, the blessed Lakṣmī engaged in song, Viṣṇu skilled in playing the deep mṛdaṅga, the gods standing all around: they serve the Lord of Mṛḍānī at the time of Pradoṣa.',[('vāgdevī dhṛta-vallakī','Sarasvatī holding the vīṇā'),('śatamakhaḥ veṇum','Indra with the flute'),('padmajaḥ tāla','Brahmā keeping time'),('ramā geya','Lakṣmī singing'),('viṣṇuḥ mṛdaṅga','Viṣṇu on the drum'),('mṛḍānī-patim','the husband of Mṛḍānī (Pārvatī)')],'<b>A concert of the gods.</b> The greatest deities become musicians for Śiva’s dance. Even Viṣṇu plays the drum.','The gods as <b>Śiva’s orchestra</b>.'),
 ('EVERY BEING PRESENT','Gandharvas, yakṣas, birds, serpents, siddhas, sādhyas, vidyādharas, the best of the gods and the troops of apsarās, and all others who dwell in the three worlds, with the hosts of beings: when Pradoṣa comes, they stand beside Hara.',[('gandharva … apsarasām','celestials of every kind'),('triloka-nilayāḥ','dwellers of the three worlds'),('bhūta-vargāḥ','the hosts of beings'),('prāpte pradoṣa-samaye','when Pradoṣa arrives'),('hara-pārśva-saṃsthāḥ','standing at Hara’s side')],'<b>Everyone.</b> No being is left out of the twilight gathering.','At Pradoṣa <b>every being stands with Śiva</b>.'),
 ('ŚIVA ALONE','Therefore at Pradoṣa Śiva alone is to be worshipped, not the others, Hari, Brahmā and the rest; when Maheśa is worshipped there according to rule, all the lords of the gods are pleased.',[('ataḥ','therefore'),('śiva eka eva pūjyaḥ','Śiva alone is to be worshipped'),('hari-padmaja-ādyāḥ','Viṣṇu, Brahmā and the rest'),('vidhinā ijyamāne','being worshipped by rule'),('sarve prasīdanti','all are pleased')],'<b>Not rivalry.</b> The point is not that Viṣṇu is lesser, but that at this hour all the gods are with Śiva: worship him and you worship them.','Worship Śiva at Pradoṣa, <b>and all the gods are pleased</b>.'),
 ('THE SAGE TO THE WIDOW (1)','This son of yours was, in a former life, an excellent brahmin; he spent his life accepting gifts, not in giving and other good deeds.',[('eṣa te tanayaḥ','this son of yours'),('pūrva-janmani','in a former life'),('pratigrahaiḥ','by accepting gifts'),('na dāna-ādyaiḥ','not by giving and the like')],'<b>The story enters the hymn.</b> These are Śāṇḍilya’s words to the widow about her son ('+L(2,'Part 3')+').','A life of only taking <b>brings poverty</b>.'),
 ('THE SAGE TO THE WIDOW (2)','That is why your son has fallen into poverty, O brahmin lady. To remove that fault, let him take refuge in Śaṅkara.',[('ataḥ dāridryam āpannaḥ','so he has fallen into poverty'),('dvija-bhāmini','O brahmin lady'),('tad-doṣa-parihāra-artham','to remove that fault'),('śaraṇam yātu śaṅkaram','let him take refuge in Śaṅkara')],'<b>The remedy.</b> Refuge in Śiva through Pradoṣa. The hymn ends where the vow begins.','The remedy: <b>take refuge in Śaṅkara</b>.')]
pp=[foreword(i,['The Skanda Purāṇa gives Pradoṣa its own hymn: the <b>Pradoṣa Stotrāṣṭakam</b>. It opens with a solemn declaration, paints the scene of Śiva’s twilight dance on Kailāsa with the gods as his orchestra, and closes with the sage Śāṇḍilya’s words from the vrata story ('+L(2,'Part 3')+').','Here is every verse in IAST, with its meaning, key words and a note. Read it slowly at twilight on the next Trayodaśī.'],[('z','Eight verses or nine?'),('b','Seven of praise and two of the story in this edition. The title says “eight”; editions differ.')]),
 glance([('Name','Pradoṣa Stotrāṣṭakam'),('Source','Skanda Purāṇa (as given in the colophon)'),('Edition','sanskritdocuments.org, pradosha8 (proofread by Ravin Bhalekar)'),('Verses','9: seven of praise (1–7), two from the vrata story (8–9)'),('Metre','Mostly vasantatilakā; verse 5 śārdūlavikrīḍita; 8–9 anuṣṭubh'),('When sung','At the Pradoṣa worship, before the kathā')],svg(560,140,'A palm-leaf book and a lamp at dusk',dusk()+g(220,120,1.6,book())+g(360,130,1.4,lamp())))]
for k,(t,mean,words,ins,kk) in enumerate(M):
    ln=PR[4*k:4*k+4] if k<7 else PR[28+2*(k-7):30+2*(k-7)]
    pp.append(verse(f'v{k+1}',f'VERSE {k+1}',t,ln,svg(220,160,'Śiva at twilight',dusk()+g(110,150,1,SH() if k not in (7,8) else sage('#ff8c1a')),cls=''),mean,words,ins,None,kk,'Text: sanskritdocuments.org, Pradoṣa Stotrāṣṭakam (pradosha8), ITRANS converted to IAST; one typographic correction in verse 3.'))
pp+=[R('chanting','CHANTING IT AT PRADOṢA','Where the hymn fits',svg(560,160,'A devotee chanting before a liṅga at dusk with a lamp',dusk().replace('190','160')+g(300,150,1.1,LING)+g(180,150,1,person('#c0392b',seat=True))+g(400,140,1.2,lamp())),['<b>In the worship.</b> The hymn is chanted during the Pradoṣa worship, often after the abhiṣeka and before the kathā.','<b>With other hymns.</b> Devotees also chant the <a href="/shiva/shiva-panchakshara-stotram/">Śiva Pañcākṣara Stotram</a>, the <a href="/shiva/mahamrityunjaya-mantra/">Mahāmṛtyuñjaya mantra</a> and the <a href="/shiva/lingashtakam/">Liṅgāṣṭakam</a>.','<b>Pronunciation.</b> Our <a href="/how-to-read-iast/">IAST guide</a> explains the letters.','<b>At home.</b> If you cannot reach a temple, chant it before a lamp at sunset.'],[('z','Can I just read the meaning?'),('b','Read the meaning first, then try the verses. Understanding comes before perfection.')],'Chant it <b>at twilight on Trayodaśī</b>.'),
 end(i,['<b>1.</b> The one essential: service at the Lord’s feet.','<b>2–3.</b> Neglect brings poverty; worship brings fortune.','<b>4–6.</b> Śiva dances on Kailāsa; every god and being attends.','<b>7.</b> At Pradoṣa, worship Śiva and all are pleased.','<b>8–9.</b> Śāṇḍilya to the widow: take refuge in Śaṅkara.'],'Part 5 is practical: how to keep the Pradoṣa vow, from the fast to the evening worship.','The Pradoṣa Stotrāṣṭakam'),
 sources([('Text:','sanskritdocuments.org, Pradoṣa Stotrāṣṭakam (pradosha8.itx), colophon “śrīskāndoktaṃ”.')],'the hymn’s exact place in the Skanda Purāṇa; metre identifications are ours.','Verses numbered as in the edition.')]
build(i,'PART 4 OF 8 · THE HYMN · VERSE BY VERSE',COV,'The gods as Śiva’s orchestra','Every verse of the <b>Pradoṣa Stotrāṣṭakam</b> in IAST with meaning: the essential truth, the <b>dance on Kailāsa</b>, the <b>gods’ orchestra</b>, and Śāṇḍilya’s closing words.','The Pradoṣa Stotrāṣṭakam of the Skanda Purāṇa verse by verse in IAST with meanings: the heart of the Upaniṣads, Śiva’s twilight dance on Kailāsa, the gods as his orchestra, and Śāṇḍilya’s words to the widow. Part 4 of the illustrated Pradoṣa series.',pp)
